INSERT INTO posts (id, author_id, title, body, status, mod_level, mod_conf, likes_count, created_at) VALUES
  ('p269','doc31','Остеопороз: диагностика и профилактика','Денситометрия (DXA) — золотой стандарт. T-score ≤ -2.5 — остеопороз. Кальций 1000-1200 мг/сут + витамин D. Бисфосфонаты при подтверждённом диагнозе.','approved',1,0.95,86,'2026-03-27 20:39:00'),
  ('p661','pat36','Как бросить курить?','Курю 15 лет. Пробовал пластыри — не помогло. Какие методы реально работают?','approved',1,0.92,24,'2026-02-05 18:34:00'),
  ('p1050','pat157','Как подготовиться к УЗИ брюшной полости?','Назначено УЗИ на утро. Что можно есть накануне? Нужно ли голодать? Можно ли пить воду?','approved',1,0.92,38,'2026-03-29 22:44:00'),
  ('p478','doc55','Отит у детей: когда нужен антибиотик','Острый средний отит: при температуре выше 39°C и выраженном болевом синдроме — амоксициллин. Лёгкое течение — наблюдение 48-72 часа. Обезболивание — ибупрофен.','approved',1,0.95,17,'2026-02-19 10:00:00'),
  ('p330','doc38','Остеохондроз шейного отдела','ЛФК — основа лечения. Упражнения на укрепление мышц шеи, растяжку. НПВС короткими курсами при обострении. МРТ показано при корешковом синдроме.','approved',1,0.95,103,'2026-01-13 08:58:00'),
  ('p694','pat47','Как бросить курить?','Курю 15 лет. Пробовал пластыри — не помогло. Какие методы реально работают?','approved',1,0.92,24,'2026-01-28 20:16:00'),
  ('p345','doc40','Артериальная гипертензия: когда начинать лечение','Диагноз артериальной гипертензии ставится при стойком повышении АД выше 140/90 мм рт. ст. при трёх измерениях в разные дни. Немедикаментозное лечение (диета DASH, снижение потребления соли до 5 г/сут, физическая активность 150 мин/нед) показано всем пациентам. Медикаментозная терапия начинается при АД ≥ 160/100 или при наличии факторов риска.','approved',1,0.95,62,'2026-01-06 19:15:00'),
  ('p315','doc36','Аритмия: когда стоит беспокоиться','Экстрасистолы у здоровых людей бывают, но при частоте более 6/мин и длительности — нужна консультация кардиолога. ЭКГ и холтеровское мониторирование — обязательные исследования.','approved',1,0.95,43,'2026-01-03 15:35:00'),
  ('p612','pat14','Болит колено при ходьбе по лестнице','Болит правое колено, особенно при подъёме по лестнице. Хруст при сгибании. Нужен рентген или МРТ?','approved',1,0.92,20,'2026-04-30 08:13:00'),
  ('p255','doc30','Ишемическая болезнь сердца: факторы риска','Модифицируемые: курение, гипертензия, гиперлипидемия, диабет, ожирение, гиподинамия. Немодифицируемые: возраст, пол, наследственность. Контроль — статины, аспирин, здоровый образ жизни.','approved',1,0.95,45,'2026-03-28 09:08:00'),
  ('p304','doc35','Витамин D: кому и сколько','Профилактическая доза для взрослых — 1000-2000 МЕ/сут. При дефиците (25(OH)D менее 20 нг/мл) — лечебные дозы 5000-7000 МЕ/сут на 8 недель. Контроль через 3 месяца.','approved',1,0.95,85,'2026-03-03 12:33:00'),
  ('p460','doc54','Варикозное расширение вен: что делать','Компрессионный трикотаж — основа консервативного лечения. Венотоники (диосмин). При прогрессировании — консультация флеболога для решения вопроса об оперативном лечении.','approved',1,0.95,110,'2026-01-25 20:52:00'),
  ('p142','doc17','Ишемическая болезнь сердца: факторы риска','Модифицируемые: курение, гипертензия, гиперлипидемия, диабет, ожирение, гиподинамия. Немодифицируемые: возраст, пол, наследственность. Контроль — статины, аспирин, здоровый образ жизни.','approved',1,0.95,55,'2026-04-21 18:04:00'),
  ('p820','pat86','Онемение пальцев рук по утрам','Просыпаюсь с онемевшими пальцами. Через 10 минут проходит. Это туннельный синдром?','approved',1,0.92,13,'2026-01-20 13:12:00'),
  ('p924','pat122','Можно ли заниматься спортом при гипертонии?','АД 145/90 на таблетках. Хочу ходить в тренажёрный зал. Какие нагрузки безопасны?','approved',1,0.92,30,'2025-11-10 10:05:00'),
  ('p861','pat100','Метеочувствительность — это реально?','При смене погоды болит голова, скачет давление. Врачи говорят, что метеозависимости не существует. Что делать?','approved',1,0.92,1,'2026-02-12 20:20:00'),
  ('p174','doc21','Витамин D: кому и сколько','Профилактическая доза для взрослых — 1000-2000 МЕ/сут. При дефиците (25(OH)D менее 20 нг/мл) — лечебные дозы 5000-7000 МЕ/сут на 8 недель. Контроль через 3 месяца.','approved',1,0.95,49,'2026-04-19 11:58:00'),
  ('p1083','pat170','Какие витамины пить при беременности?','Первый триместр. Гинеколог назначил фолиевую кислоту. Нужны ли ещё какие-то витамины?','approved',1,0.92,22,'2025-12-11 21:59:00'),
  ('p391','doc45','Бессонница: немедикаментозные методы','Гигиена сна: ложиться и вставать в одно время, спальня только для сна, отказ от экранов за час до сна. Когнитивно-поведенческая терапия инсомнии (КПТ-И) — первая линия лечения.','approved',1,0.95,72,'2026-02-14 20:35:00'),
  ('p825','pat87','Какие витамины пить при беременности?','Первый триместр. Гинеколог назначил фолиевую кислоту. Нужны ли ещё какие-то витамины?','approved',1,0.92,27,'2026-02-15 16:56:00'),
  ('p647','pat30','Какие витамины пить при беременности?','Первый триместр. Гинеколог назначил фолиевую кислоту. Нужны ли ещё какие-то витамины?','approved',1,0.92,19,'2026-02-10 10:21:00'),
  ('p49','doc6','Антибиотики при пневмонии','Согласно клиническим протоколам — амоксициллин/клавуланат как первая линия. Курс 7-10 дней. При атипичной пневмонии — макролиды (азитромицин). Контрольная рентгенография через 2-4 недели.','approved',1,0.95,92,'2026-01-02 20:36:00'),
  ('p1047','pat156','Какой анализ на щитовидку сдать первым?','Чувствую усталость и набираю вес. Подруга посоветовала проверить щитовидку. С чего начать?','approved',1,0.92,27,'2025-11-29 14:40:00'),
  ('p191','doc23','Железодефицитная анемия: диагностика','Ферритин ниже 30 мкг/л — дефицит железа. Гемоглобин ниже 120 г/л у женщин, ниже 130 у мужчин — анемия. Препараты железа принимать натощак, с витамином С для лучшего всасывания.','approved',1,0.95,82,'2025-12-12 13:51:00'),
  ('p228','doc26','Подагра: диета и лечение','Ограничение пуринов: красное мясо, субпродукты, пиво. Колхицин при обострении. Аллопуринол для снижения мочевой кислоты при частых приступах. Целевой уровень — менее 360 мкмоль/л.','approved',1,0.95,59,'2026-01-08 09:46:00'),
  ('p750','pat65','Сильная изжога после еды','Изжога каждый день после обеда и ужина. Пью соду, но помогает временно. Что принимать? Нужна ли гастроскопия?','approved',1,0.92,8,'2026-04-27 18:19:00'),
  ('p978','pat138','Сочетание метформина и алкоголя','Принимаю метформин при диабете 2 типа. Впереди праздники — можно ли бокал вина?','approved',1,0.92,7,'2026-02-09 12:29:00'),
  ('p36','doc4','Отит у детей: когда нужен антибиотик','Острый средний отит: при температуре выше 39°C и выраженном болевом синдроме — амоксициллин. Лёгкое течение — наблюдение 48-72 часа. Обезболивание — ибупрофен.','approved',1,0.95,9,'2026-04-16 11:31:00'),
  ('p62','doc7','Гипотиреоз: симптомы и лечение','Усталость, зябкость, прибавка веса — повод сдать ТТГ. При повышенном ТТГ назначается L-тироксин. Дозу подбираем индивидуально, контроль через 6-8 недель.','approved',1,0.95,86,'2026-04-05 18:14:00'),
  ('p721','pat56','Какие витамины пить при беременности?','Первый триместр. Гинеколог назначил фолиевую кислоту. Нужны ли ещё какие-то витамины?','approved',1,0.92,6,'2026-03-14 19:37:00'),
  ('p426','doc49','Аллергический ринит: современная терапия','Антигистаминные 2-го поколения (цетиризин, лоратадин) — первая линия. Интраназальные кортикостероиды при среднетяжёлом/тяжёлом течении. Аллергенспецифическая иммунотерапия (АСИТ) при поллинозе.','approved',1,0.95,86,'2026-03-22 22:03:00'),
  ('p793','pat78','Частые головные боли по вечерам','Уже две недели к вечеру болит голова в области висков. Связано ли это с давлением? Какие обследования пройти?','approved',1,0.92,21,'2026-03-06 17:15:00'),
  ('p107','doc13','Хронический тонзиллит: показания к операции','Абсолютные показания: паратонзиллярный абсцесс, ревматизм, гломерулонефрит. Относительные: более 7 ангин в год, или 5 ангин в год 2 года подряд, или 3 ангины в год 3 года подряд.','approved',1,0.95,81,'2026-04-12 17:24:00'),
  ('p755','pat66','Можно ли совмещать ибупрофен и парацетамол?','При высокой температуре врач сказал чередовать. Через сколько часов после ибупрофена можно парацетамол?','approved',1,0.92,14,'2026-02-12 07:14:00'),
  ('p799','pat80','Онемение пальцев рук по утрам','Просыпаюсь с онемевшими пальцами. Через 10 минут проходит. Это туннельный синдром?','approved',1,0.92,5,'2026-03-21 07:52:00'),
  ('p758','pat68','Как снизить сахар без таблеток?','Сахар натощак 6.5. Врач пока не назначает препараты. Какая диета поможет?','approved',1,0.92,3,'2026-03-17 08:38:00'),
  ('p1036','pat152','Какой анализ на щитовидку сдать первым?','Чувствую усталость и набираю вес. Подруга посоветовала проверить щитовидку. С чего начать?','approved',1,0.92,31,'2026-01-27 20:19:00'),
  ('p1097','pat174','Болит колено при ходьбе по лестнице','Болит правое колено, особенно при подъёме по лестнице. Хруст при сгибании. Нужен рентген или МРТ?','approved',1,0.92,3,'2025-11-10 19:05:00'),
  ('p227','doc26','Синдром раздражённого кишечника','Диагноз исключения: сначала исключаем органическую патологию. Диета low-FODMAP помогает 60% пациентов. Спазмолитики при болях. Пробиотики — доказательная база ограничена.','approved',1,0.95,107,'2026-04-27 22:23:00'),
  ('p981','pat138','Боли в спине при сидячей работе','Работаю за компьютером по 8 часов. К концу дня ноет поясница. Какие упражнения помогут? Нужен ли МРТ?','approved',1,0.92,16,'2026-01-23 18:39:00'),
  ('p865','pat101','Болит колено при ходьбе по лестнице','Болит правое колено, особенно при подъёме по лестнице. Хруст при сгибании. Нужен рентген или МРТ?','approved',1,0.92,5,'2026-04-25 16:38:00'),
  ('p1066','pat163','Какие витамины пить при беременности?','Первый триместр. Гинеколог назначил фолиевую кислоту. Нужны ли ещё какие-то витамины?','approved',1,0.92,18,'2026-03-08 11:39:00'),
  ('p599','pat9','Красные пятна на коже','Появились красные пятна на руках и ногах, чешутся. Аллергия? Или что-то серьёзнее? К кому идти?','approved',1,0.92,33,'2026-01-18 10:13:00'),
  ('p944','pat127','Тяжесть в ногах вечером','К вечеру ноги отекают, ощущение тяжести. Вены видны, но не выпирают. Это начало варикоза?','approved',1,0.92,4,'2026-04-03 20:05:00'),
  ('p367','doc42','Железодефицитная анемия: диагностика','Ферритин ниже 30 мкг/л — дефицит железа. Гемоглобин ниже 120 г/л у женщин, ниже 130 у мужчин — анемия. Препараты железа принимать натощак, с витамином С для лучшего всасывания.','approved',1,0.95,87,'2025-12-17 11:49:00'),
  ('p790','pat77','Какие витамины пить при беременности?','Первый триместр. Гинеколог назначил фолиевую кислоту. Нужны ли ещё какие-то витамины?','approved',1,0.92,35,'2026-04-14 19:09:00'),
  ('p55','doc6','Профилактика ОРВИ у детей','Закаливание, проветривание помещений, промывание носа физраствором. Вакцинация от гриппа ежегодно. Витамин D в профилактической дозе круглогодично.','approved',1,0.95,59,'2026-03-31 16:40:00'),
  ('p682','pat43','Болят суставы пальцев рук','Утренняя скованность 30-40 минут. Пальцы опухают. Ревматоидный артрит? Какие анализы сдать?','approved',1,0.92,43,'2026-02-08 20:34:00'),
  ('p757','pat67','Боль в горле уже неделю','Горло болит 7 дней, не проходит. Полоскание и пастилки не помогают. Нужен ли антибиотик?','approved',1,0.92,40,'2026-04-16 08:24:00'),
  ('p795','pat79','Красные пятна на коже','Появились красные пятна на руках и ногах, чешутся. Аллергия? Или что-то серьёзнее? К кому идти?','approved',1,0.92,29,'2026-02-12 14:05:00'),
