  ('p395','doc46','Аллергический ринит: современная терапия','Антигистаминные 2-го поколения (цетиризин, лоратадин) — первая линия. Интраназальные кортикостероиды при среднетяжёлом/тяжёлом течении. Аллергенспецифическая иммунотерапия (АСИТ) при поллинозе.','approved',1,0.95,14,'2026-04-22 08:55:00'),
  ('p111','doc13','Цистит у женщин: лечение и профилактика','Эмпирическая антибиотикотерапия: фосфомицин однократно или нитрофурантоин 5-7 дней. Обильное питьё. Профилактика: D-манноза, клюква (доказательства ограничены), гигиена.','approved',1,0.95,110,'2025-12-29 20:21:00'),
  ('p806','pat82','Онемение пальцев рук по утрам','Просыпаюсь с онемевшими пальцами. Через 10 минут проходит. Это туннельный синдром?','approved',1,0.92,6,'2026-03-14 18:44:00'),
  ('p714','pat53','Красные пятна на коже','Появились красные пятна на руках и ногах, чешутся. Аллергия? Или что-то серьёзнее? К кому идти?','approved',1,0.92,36,'2025-11-13 12:54:00'),
  ('p1133','pat185','Как бросить курить?','Курю 15 лет. Пробовал пластыри — не помогло. Какие методы реально работают?','approved',1,0.92,17,'2026-02-08 07:35:00'),
  ('p187','doc22','Гипотиреоз: симптомы и лечение','Усталость, зябкость, прибавка веса — повод сдать ТТГ. При повышенном ТТГ назначается L-тироксин. Дозу подбираем индивидуально, контроль через 6-8 недель.','approved',1,0.95,100,'2026-02-22 16:48:00'),
  ('p824','pat87','Как снизить сахар без таблеток?','Сахар натощак 6.5. Врач пока не назначает препараты. Какая диета поможет?','approved',1,0.92,36,'2026-01-30 22:37:00'),
  ('p732','pat59','Какие витамины пить при беременности?','Первый триместр. Гинеколог назначил фолиевую кислоту. Нужны ли ещё какие-то витамины?','approved',1,0.92,42,'2026-03-17 22:58:00'),
  ('p690','pat46','Ребёнок жалуется на боль в животе','Дочери 6 лет, второй день говорит что болит живот. Температуры нет. Когда нужно к врачу?','approved',1,0.92,44,'2026-02-26 07:50:00'),
  ('p157','doc19','Витамин D: кому и сколько','Профилактическая доза для взрослых — 1000-2000 МЕ/сут. При дефиците (25(OH)D менее 20 нг/мл) — лечебные дозы 5000-7000 МЕ/сут на 8 недель. Контроль через 3 месяца.','approved',1,0.95,85,'2026-04-14 17:55:00'),
  ('p815','pat85','Можно ли совмещать ибупрофен и парацетамол?','При высокой температуре врач сказал чередовать. Через сколько часов после ибупрофена можно парацетамол?','approved',1,0.92,42,'2025-12-03 10:24:00'),
  ('p392','doc45','Антибиотики при пневмонии','Согласно клиническим протоколам — амоксициллин/клавуланат как первая линия. Курс 7-10 дней. При атипичной пневмонии — макролиды (азитромицин). Контрольная рентгенография через 2-4 недели.','approved',1,0.95,31,'2026-02-08 14:16:00'),
  ('p541','doc63','Коронавирус: актуальные рекомендации','Вакцинация остаётся основным методом профилактики тяжёлого течения. При лёгком течении — симптоматическое лечение. Противовирусная терапия (нирматрелвир/ритонавир) при факторах риска.','approved',1,0.95,51,'2026-01-10 09:41:00'),
  ('p113','doc13','Остеохондроз шейного отдела','ЛФК — основа лечения. Упражнения на укрепление мышц шеи, растяжку. НПВС короткими курсами при обострении. МРТ показано при корешковом синдроме.','approved',1,0.95,37,'2026-02-18 17:42:00'),
  ('p1049','pat156','Нужно ли удалять родинку?','Родинка на спине стала больше и изменила цвет. Стоит ли беспокоиться? К какому врачу?','approved',1,0.92,15,'2025-12-01 19:50:00'),
  ('p591','pat7','Запор у грудничка — что делать?','Ребёнку 3 месяца, на грудном вскармливании. Стул раз в 3-4 дня. Нормально ли это?','approved',1,0.92,4,'2026-03-13 08:25:00'),
  ('p845','pat94','Можно ли совмещать ибупрофен и парацетамол?','При высокой температуре врач сказал чередовать. Через сколько часов после ибупрофена можно парацетамол?','approved',1,0.92,22,'2026-02-15 19:05:00'),
  ('p209','doc24','Витамин D: кому и сколько','Профилактическая доза для взрослых — 1000-2000 МЕ/сут. При дефиците (25(OH)D менее 20 нг/мл) — лечебные дозы 5000-7000 МЕ/сут на 8 недель. Контроль через 3 месяца.','approved',1,0.95,59,'2026-01-01 11:18:00'),
  ('p301','doc35','Камни в почках: профилактика рецидивов','Водный режим — не менее 2.5 л жидкости в сутки. При кальциевых камнях — ограничение оксалатов (шпинат, шоколад, орехи). Цитратная терапия. УЗИ почек каждые 6 месяцев.','approved',1,0.95,44,'2025-11-29 20:37:00'),
  ('p1057','pat161','Как правильно измерять давление дома?','Купил тонометр. Утром одно значение, вечером другое. Когда измерять? Сколько раз?','approved',1,0.92,18,'2026-04-30 21:35:00'),
  ('p98','doc12','Целевой уровень HbA1c при диабете 2 типа','Согласно клиническим рекомендациям, для большинства пациентов цель HbA1c менее 7%. У пожилых — допустимо 7.5-8%. У молодых без осложнений — стремимся к 6.5%. Контроль каждые 3 месяца.','approved',1,0.95,19,'2025-12-03 20:33:00'),
  ('p508','doc58','Синдром раздражённого кишечника','Диагноз исключения: сначала исключаем органическую патологию. Диета low-FODMAP помогает 60% пациентов. Спазмолитики при болях. Пробиотики — доказательная база ограничена.','approved',1,0.95,26,'2026-02-15 21:31:00'),
  ('p210','doc24','Артериальная гипертензия: когда начинать лечение','Диагноз артериальной гипертензии ставится при стойком повышении АД выше 140/90 мм рт. ст. при трёх измерениях в разные дни. Немедикаментозное лечение (диета DASH, снижение потребления соли до 5 г/сут, физическая активность 150 мин/нед) показано всем пациентам. Медикаментозная терапия начинается при АД ≥ 160/100 или при наличии факторов риска.','approved',1,0.95,78,'2026-04-07 18:15:00'),
  ('p364','doc42','Артериальная гипертензия: когда начинать лечение','Диагноз артериальной гипертензии ставится при стойком повышении АД выше 140/90 мм рт. ст. при трёх измерениях в разные дни. Немедикаментозное лечение (диета DASH, снижение потребления соли до 5 г/сут, физическая активность 150 мин/нед) показано всем пациентам. Медикаментозная терапия начинается при АД ≥ 160/100 или при наличии факторов риска.','approved',1,0.95,59,'2025-12-26 09:02:00'),
  ('p888','pat109','Хронический насморк — аллергия?','Нос заложен круглый год. Капли не помогают. Аллергия или полипы? К кому обратиться?','approved',1,0.92,40,'2025-12-06 13:16:00')
INSERT INTO posts (id, author_id, title, body, status, mod_level, mod_conf, likes_count, created_at) VALUES
  ('p42','doc5','Панкреатит: диета при обострении','Первые 2-3 дня — голод, затем стол №5п. Дробное питание 5-6 раз в сутки. Исключить алкоголь, жирное, жареное, острое. Ферменты (панкреатин) с каждым приёмом пищи.','approved',1,0.95,85,'2026-04-22 19:20:00'),
  ('p66','doc8','Катаракта: когда оперировать','Показание — снижение зрения, мешающее повседневной жизни. Факоэмульсификация с имплантацией ИОЛ — золотой стандарт. Операция амбулаторная, под местной анестезией, 15-20 минут.','approved',1,0.95,42,'2025-12-04 09:58:00'),
  ('p83','doc10','Дерматит: разбираемся в видах','Атопический — наследственная предрасположенность, сухость кожи, зуд. Контактный — от раздражителей. Себорейный — на волосистой части головы. Лечение: эмоленты, топические стероиды, антигистаминные.','approved',1,0.95,100,'2026-03-19 20:37:00'),
  ('p819','pat86','Ребёнок часто болеет ОРВИ','Сыну 4 года, болеет каждый месяц. Температура, насморк, кашель. Нормально ли это? Нужен ли иммунолог?','approved',1,0.92,44,'2026-02-14 16:53:00'),
